package com.taller.portal;
import com.taller.portal.dto.AuthDtos.RecoveryConfirm; import com.taller.portal.model.*; import com.taller.portal.repository.*; import com.taller.portal.service.PasswordRecoveryService; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.LocalDateTime; import java.util.HexFormat; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.test.web.servlet.MockMvc; import org.springframework.transaction.annotation.Transactional; import static org.junit.jupiter.api.Assertions.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
/** Cubre el ciclo seguro de recuperación contra H2 y Flyway. */
@SpringBootTest @AutoConfigureMockMvc @Transactional class PasswordRecoveryServiceTest {
 @Autowired PasswordRecoveryService service; @Autowired UserRepository users; @Autowired PasswordResetTokenRepository tokens; @Autowired RoleRepository roles; @Autowired PasswordEncoder encoder; @Autowired MockMvc mvc; User user;
 @BeforeEach void setup(){user=new User();user.nombre="Prueba Recuperación";user.email="recuperacion@taller.local";user.celular="5512345678";user.passwordHash=encoder.encode("anterior-segura");user.rol=roles.findByNombre(RoleName.CLIENTE).orElseThrow();user=users.save(user);}
 PasswordResetToken token(String code,LocalDateTime expiry){PasswordResetToken t=new PasswordResetToken();t.usuario=user;t.tokenHash=hash(code);t.expiraEn=expiry;return tokens.save(t);} String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new RuntimeException(e);}}
 @Test void aceptaTokenValidoYLoInutiliza(){token("123456",LocalDateTime.now().plusMinutes(1));service.confirm(new RecoveryConfirm(user.email,"123456","nueva-clave"));assertTrue(encoder.matches("nueva-clave",users.findById(user.id).orElseThrow().passwordHash));assertThrows(IllegalArgumentException.class,()->service.confirm(new RecoveryConfirm(user.email,"123456","otra-clave")));}
 @Test void rechazaExpiradoReutilizadoIncorrectoYExceso(){token("123456",LocalDateTime.now().minusMinutes(1));assertThrows(IllegalArgumentException.class,()->service.confirm(new RecoveryConfirm(user.email,"123456","nueva-clave")));tokens.deleteAll();PasswordResetToken t=token("123456",LocalDateTime.now().plusMinutes(1));service.confirm(new RecoveryConfirm(user.email,"123456","nueva-clave"));assertThrows(IllegalArgumentException.class,()->service.confirm(new RecoveryConfirm(user.email,"123456","otra-clave")));tokens.deleteAll();t=token("123456",LocalDateTime.now().plusMinutes(1));for(int i=0;i<5;i++)assertThrows(IllegalArgumentException.class,()->service.confirm(new RecoveryConfirm(user.email,"000000","nueva-clave")));assertEquals(5,tokens.findById(t.id).orElseThrow().intentos);}
 @Test void usuarioInexistenteYContrasenaDebilDanRespuestaSegura() throws Exception {mvc.perform(post("/api/auth/recover/request").contentType("application/json").content("{\"identificador\":\"ausente@taller.local\"}")).andExpect(status().isNoContent());mvc.perform(post("/api/auth/recover/confirm").contentType("application/json").content("{\"identificador\":\"ausente@taller.local\",\"token\":\"123456\",\"nuevaPassword\":\"corta\"}")).andExpect(status().isBadRequest());}
}
